import React from 'react';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut } from 'react-chartjs-2';
import {
  Activity,
  Gauge,
  Zap,
  Thermometer,
  PlayCircle,
  PauseCircle,
  Wrench,
  Sparkles,
  BarChart3,
  Factory,
  Layers,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';

ChartJS.register(ArcElement, Tooltip, Legend);

const StatusChart = ({ running = 17, idle = 2, maintenance = 1 }) => {
  const navigate = useNavigate();
  const total = running + idle + maintenance || 20;

  const runningPct = Math.round((running / total) * 100);
  const idlePct = Math.round((idle / total) * 100);
  const maintPct = Math.round((maintenance / total) * 100);

  const data = {
    labels: [
      `Running (${runningPct}%)`,
      `Idle (${idlePct}%)`,
      `Maintenance (${maintPct}%)`,
    ],
    datasets: [
      {
        data: [running, idle, maintenance],
        backgroundColor: [
          '#088395',
          '#7AB2B2',
          '#f43f5e',
        ],
        borderColor: ['#ffffff', '#ffffff', '#ffffff'],
        borderWidth: 2.5,
        hoverOffset: 6,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom',
        labels: {
          color: 'var(--text-primary)',
          font: { family: "'Plus Jakarta Sans', sans-serif", size: 11, weight: '700' },
          padding: 8,
          usePointStyle: true,
          pointStyle: 'circle',
        },
      },
      tooltip: {
        backgroundColor: '#0F172A',
        titleColor: '#FFFFFF',
        bodyColor: '#E2E8F0',
        borderColor: '#E2E8F0',
        borderWidth: 1,
        padding: 8,
      },
    },
    cutout: '64%',
  };

  const statusDetails = [
    { label: 'Running', count: running, pct: runningPct, color: 'var(--status-running)', bgColor: 'var(--status-running-bg)', icon: PlayCircle },
    { label: 'Idle', count: idle, pct: idlePct, color: 'var(--status-idle)', bgColor: 'var(--status-idle-bg)', icon: PauseCircle },
    { label: 'Maint.', count: maintenance, pct: maintPct, color: 'var(--status-maintenance)', bgColor: 'var(--status-maintenance-bg)', icon: Wrench },
  ];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', justifyContent: 'space-between' }}>
      <div>
        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
          <div>
            <h3 style={{ fontSize: '1rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
              <Activity size={18} style={{ color: 'var(--status-running)' }} /> Fleet Status Breakdown
            </h3>
            <span style={{ fontSize: '0.74rem', color: 'var(--text-muted)', fontWeight: '600' }}>
              Real-Time Weaving Loom Operational Sync
            </span>
          </div>
          <span className="badge badge-running" style={{ fontWeight: '800', fontSize: '0.7rem' }}>Live Feed</span>
        </div>

        {/* Donut Chart Canvas */}
        <div style={{ height: '190px', width: '100%', position: 'relative', margin: '0.25rem 0' }}>
          <Doughnut data={data} options={options} />
          <div
            style={{
              position: 'absolute',
              top: '38%',
              left: '50%',
              transform: 'translate(-50%, -50%)',
              textAlign: 'center',
              pointerEvents: 'none',
            }}
          >
            <div style={{ fontSize: '2.2rem', fontWeight: '900', color: 'var(--text-primary)', lineHeight: 1 }}>{total}</div>
            <div style={{ fontSize: '0.7rem', fontWeight: '800', color: 'var(--text-muted)', marginTop: '2px', letterSpacing: '0.5px' }}>
              TOTAL LOOMS
            </div>
          </div>
        </div>

        {/* Status Tier Pills */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.4rem', margin: '0.6rem 0' }}>
          {statusDetails.map((sd, idx) => {
            const Icon = sd.icon;
            return (
              <div
                key={idx}
                style={{
                  background: sd.bgColor,
                  border: `1px solid ${sd.color}40`,
                  borderRadius: '6px',
                  padding: '0.45rem 0.35rem',
                  textAlign: 'center',
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.2rem', fontSize: '0.68rem', fontWeight: '800', color: sd.color }}>
                  <Icon size={11} /> {sd.label}
                </div>
                <div style={{ fontSize: '1.1rem', fontWeight: '900', color: 'var(--text-primary)', margin: '1px 0' }}>
                  {sd.count} <span style={{ fontSize: '0.65rem', color: 'var(--text-muted)' }}>({sd.pct}%)</span>
                </div>
              </div>
            );
          })}
        </div>

        {/* Primary Metrics Grid Box */}
        <div
          style={{
            background: 'var(--bg-primary)',
            border: '1px solid var(--border-subtle)',
            borderRadius: '6px',
            padding: '0.65rem 0.85rem',
            display: 'grid',
            gridTemplateColumns: 'repeat(2, 1fr)',
            gap: '0.5rem',
            marginBottom: '0.6rem',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <Gauge size={14} style={{ color: 'var(--status-running)' }} />
            <div>
              <div style={{ fontSize: '0.68rem', color: 'var(--text-secondary)', fontWeight: '800' }}>FLEET OEE</div>
              <div style={{ fontSize: '0.88rem', fontWeight: '900', color: 'var(--text-primary)' }}>96.4%</div>
            </div>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <Activity size={14} style={{ color: 'var(--accent-primary)' }} />
            <div>
              <div style={{ fontSize: '0.68rem', color: 'var(--text-secondary)', fontWeight: '800' }}>OUTPUT RATE</div>
              <div style={{ fontSize: '0.88rem', fontWeight: '900', color: 'var(--text-primary)' }}>1,485 M/hr</div>
            </div>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <Zap size={14} style={{ color: 'var(--status-idle)' }} />
            <div>
              <div style={{ fontSize: '0.68rem', color: 'var(--text-secondary)', fontWeight: '800' }}>ACTIVE SENSORS</div>
              <div style={{ fontSize: '0.88rem', fontWeight: '900', color: 'var(--text-primary)' }}>136 Feeds</div>
            </div>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <Thermometer size={14} style={{ color: 'var(--status-maintenance)' }} />
            <div>
              <div style={{ fontSize: '0.68rem', color: 'var(--text-secondary)', fontWeight: '800' }}>AVG TEMP</div>
              <div style={{ fontSize: '0.88rem', fontWeight: '900', color: 'var(--text-primary)' }}>54.2°C</div>
            </div>
          </div>
        </div>

        {/* Gauges Bar */}
        <div
          style={{
            background: 'var(--bg-primary)',
            border: '1px solid var(--border-subtle)',
            borderRadius: '6px',
            padding: '0.6rem 0.85rem',
            display: 'flex',
            flexDirection: 'column',
            gap: '0.4rem',
          }}
        >
          <div style={{ fontSize: '0.72rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
              <BarChart3 size={13} style={{ color: 'var(--status-running)' }} /> Loom Speed Index
            </span>
            <span style={{ fontSize: '0.7rem', color: 'var(--status-running)', fontWeight: '800' }}>1,050 RPM (95%)</span>
          </div>
          <div style={{ height: '5px', background: 'var(--border-subtle)', borderRadius: '3px', overflow: 'hidden' }}>
            <div style={{ width: '95%', height: '100%', background: 'linear-gradient(90deg, #10b981, #38bdf8)', borderRadius: '3px' }}></div>
          </div>

          <div style={{ fontSize: '0.72rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: '2px' }}>
            <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
              <Sparkles size={13} style={{ color: 'var(--accent-primary)' }} /> Fabric Quality
            </span>
            <span style={{ fontSize: '0.7rem', color: 'var(--accent-primary)', fontWeight: '800' }}>99.1% Grade A+</span>
          </div>
          <div style={{ height: '5px', background: 'var(--border-subtle)', borderRadius: '3px', overflow: 'hidden' }}>
            <div style={{ width: '99.1%', height: '100%', background: 'linear-gradient(90deg, #2563eb, #8b5cf6)', borderRadius: '3px' }}></div>
          </div>
        </div>
      </div>

      {/* Action Footer */}
      <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.75rem' }}>
        <button
          onClick={() => navigate('/assets')}
          className="btn btn-secondary btn-sm"
          style={{ flex: 1, justifyContent: 'center', fontSize: '0.76rem', fontWeight: '700' }}
        >
          <Activity size={14} style={{ color: 'var(--status-running)' }} /> Fleet Telemetry
        </button>
        <button
          onClick={() => navigate('/plants')}
          className="btn btn-primary btn-sm"
          style={{ flex: 1, justifyContent: 'center', fontSize: '0.76rem', fontWeight: '700' }}
        >
          <Factory size={14} /> Plant Hierarchy
        </button>
      </div>
    </div>
  );
};

export default StatusChart;
